    @model_validator(mode="before")
    @classmethod
    def check_batch_mode(cls, data: Any) -> Any:
        if isinstance(data, BatchChatCompletionRequest):
            data = data.model_dump(exclude_unset=True)
        if data.get("stream"):
            raise VLLMValidationError(
                "Batch chat completions do not support streaming. "
                "Please set `stream` to False.",
                parameter="stream",
            )
        if data.get("tools"):
            raise VLLMValidationError(
                "Batch chat completions do not support tools. "
                "Please omit `tools`.",
                parameter="tools",
            )
        if data.get("use_beam_search"):
            raise VLLMValidationError(
                "Batch chat completions do not support beam search. "
                "Please set `use_beam_search` to False.",
                parameter="use_beam_search",
            )
        if data.get("logprob_token_ids") and not data.get("logprobs"):
            raise VLLMValidationError(
                "when using `logprob_token_ids`, `logprobs` must be set to true.",
                parameter="logprob_token_ids",
            )
        response_format = data.get("response_format")
        rf_type = (
            response_format.get("type")
            if isinstance(response_format, dict)
            else getattr(response_format, "type", None)
        )
        if rf_type == "structural_tag":
            validate_structural_tag_response_format(response_format)
        if (structured_outputs := data.get("structured_outputs")) is not None:
            validate_structured_outputs_structural_tag(structured_outputs)
        n = data.get("n", 1)
        if n is not None and n != 1:
            raise VLLMValidationError(
                "Batch chat completions do not support `n > 1`. Please set `n` to 1.",
            model=MODEL_NAME,
            messages=[[{"role": "user", "content": "hello"}]],
            response_format={"type": "structural_tag", "format": format_value},
        )


def test_batch_chat_rejects_streaming():
    with pytest.raises(ValidationError, match="do not support streaming"):
        BatchChatCompletionRequest(
            model=MODEL_NAME,
            messages=[[{"role": "user", "content": "hello"}]],
            stream=True,
        )


def test_batch_chat_rejects_tools():
    with pytest.raises(ValidationError, match="do not support tools"):
        BatchChatCompletionRequest(
            model=MODEL_NAME,
            messages=[[{"role": "user", "content": "hello"}]],
            tools=[
                {
                    "type": "function",
                    "function": {
                        "name": "get_weather",
                        "parameters": {"type": "object", "properties": {}},
                    },
                }
            ],
        )


def test_batch_chat_accepts_supported_request():
    request = BatchChatCompletionRequest(
        model=MODEL_NAME,
        messages=[[{"role": "user", "content": "hello"}]],
        temperature=0.5,
    )

    assert request.temperature == 0.5
    assert request.messages[0][0]["content"] == "hello"


@pytest.mark.parametrize("structural_tag", ["not json", ""])
def test_structured_outputs_structural_tag_invalid(structural_tag):
    """Malformed direct structured_outputs structural tags should be rejected."""
    with pytest.raises(
        ValidationError,
        match="Invalid structured_outputs structural_tag",
    ):
        ChatCompletionRequest(
            model=MODEL_NAME,
            messages=[{"role": "user", "content": "hello"}],
            structured_outputs={"structural_tag": structural_tag},
        )


@pytest.mark.parametrize("field_name", ["prompt_logprobs", "top_logprobs"])
def test_non_numeric_logprobs_rejected(field_name):
    """A non-numeric logprobs value must be a clean 400 validation error, not a
    TypeError from the mode='before' comparison (which surfaces as HTTP 500)."""
    with pytest.raises(ValidationError, match=f"`{field_name}` must be an integer"):
        ChatCompletionRequest(
            model=MODEL_NAME,
            messages=[{"role": "user", "content": "hello"}],
            **{field_name: "2"},
        )
