def test_batch_chat_rejects_streaming():
    with pytest.raises(ValidationError, match="do not support streaming"):
        BatchChatCompletionRequest(
            model=MODEL_NAME,
            messages=[[{"role": "user", "content": "hello"}]],
            stream=True,
        )

def test_batch_chat_rejects_tools():
    with pytest.raises(ValidationError, match="do not support tools"):
        BatchChatCompletionRequest(
            model=MODEL_NAME,
            messages=[[{"role": "user", "content": "hello"}]],
            tools=[
                {
                    "type": "function",
                    "function": {
                        "name": "get_weather",
                        "parameters": {"type": "object", "properties": {}},
                    },
                }
            ],
        )

def test_batch_chat_accepts_supported_request():
    request = BatchChatCompletionRequest(
        model=MODEL_NAME,
        messages=[[{"role": "user", "content": "hello"}]],
        temperature=0.5,
    )

assert request.temperature == 0.5
    assert request.messages[0][0]["content"] == "hello"

